class Solution {
  public int largestPrime(int n) {
    boolean[] composite = new boolean[n + 1];
    for (int i = 2; (long) i * i <= n; i++)
      if (!composite[i]) for (int j = i * i; j <= n; j += i) composite[j] = true;
    long sum = 0;
    int best = 0;
    for (int p = 2; p <= n; p++) {
      if (composite[p]) continue;
      sum += p;
      if (sum > n) break;
      if (!composite[(int) sum]) best = (int) sum;
    }
    return best;
  }
}
